WITH with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM payments) SELECT id, order_id, method, paid_at, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps;
